#!/bin/bash
CONFIG_FILE="${1:-sentinel.conf}"; [ -f "$CONFIG_FILE" ] || { echo "Error: configuration file not found" >&2; exit 1; }; source "$CONFIG_FILE"; declare -p SERVICES FILES_TO_WATCH ALLOWED_PORTS >/dev/null 2>&1 || { echo "Error: required configuration variables are missing" >&2; exit 1; }; log() { printf '{"timestamp":"%s","component":"%s","target":"%s","status":"%s","details":"%s"}\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$1" "$2" "$3" "$4" >> /var/log/sentinel.log; }; check_services() { for svc in "${SERVICES[@]}"; do if pgrep -f "$svc" >/dev/null; then log SERVICE "$svc" OK "Service is running"; else if eval "$svc" >/dev/null 2>&1; then log SERVICE "$svc" FIXED "Restarted service"; else log SERVICE "$svc" ALERT "Failed to restart service"; fi; fi; done; }; check_integrity() { for file in "${FILES_TO_WATCH[@]}"; do gold="/var/backups/sentinel/$(basename "$file").gold"; live_hash=$(md5sum "$file" | awk '{print $1}'); gold_hash=$(md5sum "$gold" | awk '{print $1}'); if [ "$live_hash" = "$gold_hash" ]; then log INTEGRITY "$file" OK "Integrity verified"; else cp "$gold" "$file" && log INTEGRITY "$file" FIXED "Restored file"; fi; done; }; check_ports() { for port in $(ss -lnt4 | awk 'NR>1 {split($4,a,":"); print a[2]}' | sort -n -u); do allowed=0; for p in "${ALLOWED_PORTS[@]}"; do [ "$port" = "$p" ] && allowed=1; done; if [ "$allowed" -eq 0 ]; then pid=$(lsof -t -iTCP:$port -sTCP:LISTEN 2>/dev/null | head -1); [ -n "$pid" ] && kill -9 "$pid" && log PORT "$port" ALERT "Killed rogue process"; fi; done; }; check_services; check_integrity; check_ports
